import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { teamLogic } from 'scenes/teamLogic'

import { TeamPublicType, TeamType } from '~/types'

export const DEFAULT_WAIT_PERIOD_DAYS = 14
export const MAX_WAIT_PERIOD_DAYS = 365

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface surveyGlobalWaitPeriodLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    currentTeamLoading: boolean // teamLogic
    days: number | undefined
    draftDays: number | null | undefined
    draftEnabled: boolean | null
    enabled: boolean
    nextDays: number | null
    saveDisabledReason: string | null
    savedDays: number | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface surveyGlobalWaitPeriodLogicActions {
    updateCurrentTeam: (payload: Partial<TeamType>) => Partial<TeamType> // teamLogic
    updateCurrentTeamSuccess: (
        currentTeam: TeamPublicType | TeamType,
        payload?: Partial<TeamType> | undefined
    ) => {
        currentTeam: TeamPublicType | TeamType
        payload?: Partial<TeamType>
    } // teamLogic
    save: () => {
        value: true
    }
    setDays: (days: number | undefined) => {
        days: number | undefined
    }
    setEnabled: (enabled: boolean) => {
        enabled: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface surveyGlobalWaitPeriodLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        savedDays: (currentTeam: TeamPublicType | TeamType | null) => number | null
        enabled: (draftEnabled: boolean | null, savedDays: number | null) => boolean
        days: (draftDays: number | null | undefined, savedDays: number | null) => number | undefined
        nextDays: (enabled: boolean, days: number | undefined) => number | null
        saveDisabledReason: (
            currentTeam: TeamPublicType | TeamType | null,
            nextDays: number | null,
            savedDays: number | null
        ) => string | null
    }
}

export type surveyGlobalWaitPeriodLogicType = MakeLogicType<
    surveyGlobalWaitPeriodLogicValues,
    surveyGlobalWaitPeriodLogicActions,
    Record<string, any>,
    surveyGlobalWaitPeriodLogicMeta
>

function savedWaitPeriodChanged(payload: Partial<TeamType> | undefined): boolean {
    return !!payload?.survey_config && 'seenSurveyWaitPeriodInDays' in payload.survey_config
}

export const surveyGlobalWaitPeriodLogic = kea<surveyGlobalWaitPeriodLogicType>([
    path(['products', 'surveys', 'frontend', 'components', 'surveyGlobalWaitPeriodLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam', 'currentTeamLoading']],
        actions: [teamLogic, ['updateCurrentTeam', 'updateCurrentTeamSuccess']],
    })),
    actions({
        setEnabled: (enabled: boolean) => ({ enabled }),
        setDays: (days: number | undefined) => ({ days }),
        save: true,
    }),
    reducers({
        // null means no edit, so the control shows the saved value, also after a late project load.
        draftEnabled: [
            null as boolean | null,
            {
                setEnabled: (_, { enabled }) => enabled,
                updateCurrentTeamSuccess: (state, { payload }) => (savedWaitPeriodChanged(payload) ? null : state),
            },
        ],
        draftDays: [
            null as number | undefined | null,
            {
                setDays: (_, { days }) => days,
                updateCurrentTeamSuccess: (state, { payload }) => (savedWaitPeriodChanged(payload) ? null : state),
            },
        ],
    }),
    selectors({
        savedDays: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): number | null =>
                currentTeam?.survey_config?.seenSurveyWaitPeriodInDays || null,
        ],
        enabled: [
            (s) => [s.draftEnabled, s.savedDays],
            (draftEnabled: boolean | null, savedDays: number | null): boolean => draftEnabled ?? !!savedDays,
        ],
        days: [
            (s) => [s.draftDays, s.savedDays],
            (draftDays: number | null | undefined, savedDays: number | null): number | undefined =>
                draftDays !== null ? draftDays : (savedDays ?? DEFAULT_WAIT_PERIOD_DAYS),
        ],
        nextDays: [
            (s) => [s.enabled, s.days],
            (enabled: boolean, days: number | undefined): number | null => (enabled ? (days ?? null) : null),
        ],
        saveDisabledReason: [
            (s) => [s.currentTeam, s.nextDays, s.savedDays],
            (
                currentTeam: TeamPublicType | TeamType | null,
                nextDays: number | null,
                savedDays: number | null
            ): string | null => {
                if (!currentTeam) {
                    return 'Loading project settings'
                }
                if (
                    nextDays !== null &&
                    (!Number.isInteger(nextDays) || nextDays < 1 || nextDays > MAX_WAIT_PERIOD_DAYS)
                ) {
                    return `Enter a whole number of days from 1 to ${MAX_WAIT_PERIOD_DAYS}.`
                }
                return nextDays === savedDays ? 'No changes to save' : null
            },
        ],
    }),
    listeners(({ actions, values }) => ({
        save: () => {
            // The server merges survey_config, so send only this key and keep other admins' edits.
            actions.updateCurrentTeam({ survey_config: { seenSurveyWaitPeriodInDays: values.nextDays } })
        },
    })),
])
